<script setup lang="ts">
import{onMounted,reactive,watch}from'vue';import{storeToRefs}from'pinia';import{useAiSettingsStore,type AiSettingsForm}from'../stores/aiSettings'
const store=useAiSettingsStore(),{view,status,busy}=storeToRefs(store),form=reactive<AiSettingsForm>({mode:'DEMO',baseUrl:'',model:'',apiKey:'',persistKey:false,maxOutputTokens:1024,dailyLimit:30})
watch(view,value=>{if(value)Object.assign(form,{mode:value.mode,baseUrl:value.baseUrl,model:value.model,apiKey:'',persistKey:value.persistKey,maxOutputTokens:value.maxOutputTokens,dailyLimit:value.dailyLimit})},{immediate:true})
onMounted(()=>void store.load());const save=async()=>{try{await store.save({...form});form.apiKey=''}catch{form.apiKey=''}};const clear=async()=>{await store.clear();form.apiKey=''}
</script>
<template><div class="page settings-page"><p class="eyebrow">SETTINGS</p><h1>AI 设置</h1><p class="security-note">密钥提交后立即从浏览器内存和输入框清除，绝不写入 localStorage、sessionStorage 或 URL。仅 Windows 且 DPAPI 可用时才能选择安全持久化，否则仅保存在后端进程内存中。</p><form class="settings-form" @submit.prevent="save"><label>模式<select v-model="form.mode"><option value="DEMO">Demo（离线演示）</option><option value="DEEPSEEK">DeepSeek</option></select></label><label>Base URL<input v-model="form.baseUrl" type="url"></label><label>模型<input v-model="form.model"></label><label>API 密钥<input v-model="form.apiKey" type="password" autocomplete="new-password" :placeholder="view?.maskedKey||'未配置'"></label><label><input v-model="form.persistKey" type="checkbox" :disabled="!view?.persistenceAvailable">使用 DPAPI 持久化</label><label>最大输出 token<input v-model.number="form.maxOutputTokens" type="number" min="64"></label><label>每日调用上限<input v-model.number="form.dailyLimit" type="number" min="1"></label><p>今日已用：{{view?.todayUsed??0}} / {{form.dailyLimit}}</p><div><button class="button primary" :disabled="busy">保存</button><button type="button" class="button secondary" :disabled="busy" @click="store.test">测试连接</button><button type="button" class="button secondary" @click="clear">清除密钥</button></div></form><p aria-live="polite">{{status}}</p></div></template>
